import{_ as o,o as r,c as t,ae as s}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Functional Requirements — heliosApp Phase 3","description":"","frontmatter":{},"headers":[],"relativePath":"specs/FR.md","filePath":"specs/FR.md"}'),n={name:"specs/FR.md"};function a(c,e,i,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="functional-requirements-—-heliosapp-phase-3" tabindex="-1">Functional Requirements — heliosApp Phase 3 <a class="header-anchor" href="#functional-requirements-—-heliosapp-phase-3" aria-label="Permalink to &quot;Functional Requirements — heliosApp Phase 3&quot;">​</a></h1><p><strong>REPOID:</strong> HELIOSAPP <strong>Phase:</strong> 3 — Hexagonal Architecture + Traceability <strong>Date:</strong> 2026-06-15</p><hr><h2 id="fr-001-—-local-bus-decoupled-message-dispatch" tabindex="-1">FR-001 — Local Bus Decoupled Message Dispatch <a class="header-anchor" href="#fr-001-—-local-bus-decoupled-message-dispatch" aria-label="Permalink to &quot;FR-001 — Local Bus Decoupled Message Dispatch&quot;">​</a></h2><p><strong>Title:</strong> All inter-component communication MUST flow through a single <code>ILocalBusPort</code> contract.</p><p><strong>Description:</strong> The runtime must route every command dispatch and event fan-out through the <code>ILocalBusPort</code> primary port. No component may call another component&#39;s concrete type directly. This enforces decoupling and enables test-double injection.</p><p><strong>Acceptance Criteria:</strong></p><ul><li><code>ILocalBusPort.dispatch()</code> returns a correlated <code>ResponseEnvelope</code> for every registered method.</li><li>Unregistered method invocations return a structured error response (not a thrown exception).</li><li>Event fan-out reaches all active subscribers before <code>publish()</code> resolves.</li></ul><p><strong>Port:</strong> <code>apps/runtime/src/ports/ILocalBusPort.ts</code><strong>Spec:</strong> <code>docs/specs/002-local-bus-v1-protocol-and-envelope/</code></p><hr><h2 id="fr-002-—-command-correlation-guarantee" tabindex="-1">FR-002 — Command Correlation Guarantee <a class="header-anchor" href="#fr-002-—-command-correlation-guarantee" aria-label="Permalink to &quot;FR-002 — Command Correlation Guarantee&quot;">​</a></h2><p><strong>Title:</strong> Every dispatched command MUST receive a response with a matching <code>correlation_id</code>.</p><p><strong>Description:</strong> The bus must track in-flight commands by <code>id</code> / <code>correlation_id</code> so callers can await their own response without observing responses to other concurrent commands.</p><p><strong>Acceptance Criteria:</strong></p><ul><li>Response <code>correlation_id</code> equals the originating command <code>id</code>.</li><li>Concurrent distinct commands produce independent correlated responses.</li><li>Timeout after configurable TTL with <code>BUS_TIMEOUT</code> error code.</li></ul><p><strong>Port:</strong> <code>apps/runtime/src/ports/ILocalBusPort.ts</code><strong>Spec:</strong> <code>docs/specs/002-local-bus-v1-protocol-and-envelope/</code></p><hr><h2 id="fr-003-—-workspace-isolation-and-unique-naming" tabindex="-1">FR-003 — Workspace Isolation and Unique Naming <a class="header-anchor" href="#fr-003-—-workspace-isolation-and-unique-naming" aria-label="Permalink to &quot;FR-003 — Workspace Isolation and Unique Naming&quot;">​</a></h2><p><strong>Title:</strong> Workspaces MUST be uniquely named and isolated by a typed <code>ws_</code> prefixed ID.</p><p><strong>Description:</strong> The <code>IWorkspacePort</code> must reject duplicate workspace names and assign a ULID-based <code>ws_</code> ID to every workspace. Each workspace represents an independently addressable file-system root for agent sessions.</p><p><strong>Acceptance Criteria:</strong></p><ul><li><code>create()</code> throws <code>WORKSPACE_NAME_CONFLICT</code> when the name already exists in state <code>active</code>.</li><li>All returned <code>Workspace.id</code> values match <code>/^ws_[0-9A-Z]{26}$/</code>.</li><li><code>delete()</code> rejects with <code>WORKSPACE_HAS_ACTIVE_SESSIONS</code> when active sessions remain.</li></ul><p><strong>Port:</strong> <code>apps/runtime/src/ports/IWorkspacePort.ts</code><strong>Spec:</strong> <code>docs/specs/003-workspace-and-project-metadata-persistence/</code></p><hr><h2 id="fr-004-—-append-only-audit-trail" tabindex="-1">FR-004 — Append-Only Audit Trail <a class="header-anchor" href="#fr-004-—-append-only-audit-trail" aria-label="Permalink to &quot;FR-004 — Append-Only Audit Trail&quot;">​</a></h2><p><strong>Title:</strong> The runtime MUST write every bus event to a durable, append-only audit store.</p><p><strong>Description:</strong> <code>IAuditPort.append()</code> must be called for every <code>CommandEnvelope</code>, <code>ResponseEnvelope</code>, and <code>EventEnvelope</code> that passes through the bus. The store must support structured query, time-bounded export, and retention-policy purge.</p><p><strong>Acceptance Criteria:</strong></p><ul><li><code>append()</code> never throws; storage failures are logged and swallowed.</li><li><code>export()</code> returns a <code>RuntimeAuditBundle</code> with count = number of records in the time window.</li><li><code>purge(before)</code> deletes only records with <code>recorded_at &lt; before</code>.</li></ul><p><strong>Port:</strong> <code>apps/runtime/src/ports/IAuditPort.ts</code><strong>Spec:</strong> <code>docs/specs/024-audit-logging-and-session-replay/</code></p><hr><h2 id="fr-005-—-pluggable-ai-inference-provider" tabindex="-1">FR-005 — Pluggable AI Inference Provider <a class="header-anchor" href="#fr-005-—-pluggable-ai-inference-provider" aria-label="Permalink to &quot;FR-005 — Pluggable AI Inference Provider&quot;">​</a></h2><p><strong>Title:</strong> AI inference MUST be accessed exclusively through the <code>IProviderPort</code> secondary port.</p><p><strong>Description:</strong> The domain core must never reference Anthropic SDK types directly; it must program to <code>IProviderPort</code>. This allows alternative providers (local models, test doubles) to be swapped without changes to core logic.</p><p><strong>Acceptance Criteria:</strong></p><ul><li><code>infer()</code> returns <code>InferenceResponse</code> with populated <code>text</code>, <code>inputTokens</code>, and <code>outputTokens</code>.</li><li><code>healthCheck()</code> never throws; returns <code>{ ok: false, reason: string }</code> on network failure.</li><li>Providers register with a unique <code>providerId</code> string; duplicate registration throws <code>PROVIDER_CONFLICT</code>.</li></ul><p><strong>Port:</strong> <code>apps/runtime/src/ports/IProviderPort.ts</code><strong>Spec:</strong> <code>docs/specs/025-provider-adapter-interface-and-lifecycle/</code></p>',37)])])}const g=o(n,[["render",a]]);export{h as __pageData,g as default};
